"""Lazy memory-mapped windows with stable per-window identifiers."""
import csv
import numpy as np
import torch
from torch.utils.data import Dataset
from src.utils.tracking import read_json


class WindowDataset(Dataset):
    def __init__(self, cache, subjects, scaler=None):
        self.subjects = list(subjects)
        self.scaler = scaler
        self.arrays, self.rows, self.indices, self.cache_keys = {}, [], [], {}
        for subject in subjects:
            folder = cache / subject
            self.arrays[subject] = np.load(folder / 'windows.npy', mmap_mode='r')
            self.cache_keys[subject] = read_json(folder / 'metadata.json')['cache_key']
            with (folder / 'windows.csv').open(encoding='utf-8', newline='') as stream:
                rows = list(csv.DictReader(stream))
            if len(rows) != len(self.arrays[subject]):
                raise ValueError('Cache rows and windows disagree.')
            for i, row in enumerate(rows):
                row['label'] = int(row['label'])
                self.rows.append(row)
                self.indices.append((subject, i))
        self.labels = np.array([r['label'] for r in self.rows], dtype=np.int64)

    def __len__(self):
        return len(self.rows)

    def __getitem__(self, index):
        subject, offset = self.indices[index]
        x = np.array(self.arrays[subject][offset], copy=True)
        if self.scaler is not None:
            x = self.scaler.transform(x)
        return torch.from_numpy(x), int(self.labels[index]), index

"""Inspect official trusted WESAD pickle files one subject at a time."""
import pickle
import numpy as np
from src.data.splits import SUBJECTS
from src.utils.tracking import file_hash, write_json, now

RATES = {'wrist': {'ACC': 32, 'BVP': 64, 'EDA': 4, 'TEMP': 4},
         'chest': {k: 700 for k in ('ACC', 'ECG', 'EMG', 'EDA', 'Temp', 'Resp')}}


def load_subject(root, subject):
    path = root / subject / (subject + '.pkl')
    with path.open('rb') as stream:
        data = pickle.load(stream, encoding='latin1')
    if not {'signal', 'label', 'subject'} <= data.keys():
        raise ValueError(f'{subject}: missing WESAD keys')
    if data['subject'] != subject:
        raise ValueError(f'{subject}: pickle subject identity mismatch')
    return data


def inspect_subject(data, subject):
    labels = np.asarray(data['label'])
    if labels.ndim != 1 or not np.isfinite(labels).all() or not np.isin(labels, np.arange(8)).all():
        raise ValueError(f'{subject}: invalid labels')
    report = {'subject': subject, 'keys': sorted(data), 'labels': {str(k): int(v) for k, v in zip(*np.unique(labels, return_counts=True))},
              'label_shape': list(labels.shape), 'label_dtype': str(labels.dtype), 'label_rate': 700,
              'duration_seconds': len(labels) / 700, 'signals': {}}
    for device, signals in data['signal'].items():
        report['signals'][device] = {}
        for name, signal in signals.items():
            rate = RATES[device][name]
            expected_channels = 3 if name == 'ACC' else 1
            if signal.ndim != 2 or signal.shape[1] != expected_channels or not len(signal):
                raise ValueError(f'{subject}/{device}/{name}: invalid shape {signal.shape}')
            # Bounded temporary arrays on machines with limited RAM.
            finite = all(np.isfinite(signal[i:i + 100000]).all() for i in range(0, len(signal), 100000))
            duration = len(signal) / rate
            if not finite or abs(duration - len(labels) / 700) > 1 / rate + 1 / 700:
                raise ValueError(f'{subject}/{device}/{name}: nonfinite values or duration mismatch')
            report['signals'][device][name] = {'shape': list(signal.shape), 'dtype': str(signal.dtype),
                'rate': rate, 'duration_seconds': duration, 'finite': finite,
                'min': float(signal.min()), 'max': float(signal.max()),
                'alignment_delta_seconds': duration - len(labels) / 700}
    for name in ('ACC', 'BVP', 'EDA'):
        if name not in data['signal']['wrist']:
            raise ValueError(f'{subject}: missing wrist {name}')
    report['range_policy'] = 'Observed ranges recorded; no physiological clipping or unit conversion.'
    return report


def inspect_dataset(root, output):
    report = {'started_at': now(), 'root': str(root), 'subjects': [], 'status': 'running'}
    try:
        for subject in SUBJECTS:
            print(f'[INSPECT] {subject}', flush=True)
            data = load_subject(root, subject)
            item = inspect_subject(data, subject)
            item['raw_sha256'] = file_hash(root / subject / (subject + '.pkl'))
            report['subjects'].append(item)
            del data
            write_json(output, report)
        report['status'] = 'completed'
    except BaseException as exc:
        report.update(status='failed', error=repr(exc))
        raise
    finally:
        report['ended_at'] = now()
        write_json(output, report)
    return report

"""Numerically stable channel statistics fitted exclusively on training windows."""
import numpy as np
from src.utils.tracking import write_json


class ChannelScaler:
    def fit(self, dataset):
        if dataset.scaler is not None:
            raise ValueError('Fit requires unnormalized training windows.')
        count, mean, m2 = 0, None, None
        for subject in dataset.subjects:
            array = dataset.arrays[subject]
            for start in range(0, len(array), 64):
                block = np.asarray(array[start:start + 64], dtype=np.float64).transpose(1, 0, 2).reshape(array.shape[1], -1)
                n = block.shape[1]
                bm = block.mean(axis=1)
                b2 = ((block - bm[:, None]) ** 2).sum(axis=1)
                if mean is None:
                    mean, m2, count = bm, b2, n
                else:
                    delta = bm - mean
                    m2 += b2 + delta ** 2 * count * n / (count + n)
                    mean += delta * n / (count + n)
                    count += n
        self.mean = mean.astype(np.float32)
        self.std = np.sqrt(m2 / count).astype(np.float32)
        self.std[self.std < 1e-8] = 1
        self.subjects, self.count = dataset.subjects, count
        return self

    def transform(self, x):
        return ((x - self.mean[:, None]) / self.std[:, None]).astype(np.float32)

    def save(self, path):
        write_json(path, {'mean': self.mean.tolist(), 'std': self.std.tolist(),
                          'train_subjects': self.subjects, 'sample_count_per_channel': self.count,
                          'weighting': 'all timesteps in training windows, including overlap', 'ddof': 0})

"""Time-based resampling with anti-aliasing for downsampling."""
import numpy as np
from math import gcd
from scipy.signal import resample_poly


def resample_signal(signal, source_rate, target_rate, target_length):
    signal = np.asarray(signal, dtype=np.float32)
    if signal.ndim != 2 or not np.isfinite(signal).all():
        raise ValueError('Signals must be finite (time, channels) arrays.')
    duration_delta = len(signal) / source_rate - target_length / target_rate
    if abs(duration_delta) > 1 / source_rate + 1 / target_rate:
        raise ValueError('Signal duration mismatch; refusing silent truncation/extension.')
    if source_rate > target_rate:
        divisor = gcd(source_rate, target_rate)
        output = resample_poly(signal, target_rate // divisor, source_rate // divisor, axis=0)
    elif source_rate < target_rate:
        times = np.arange(target_length) / target_rate
        source_times = np.arange(len(signal)) / source_rate
        output = np.stack([np.interp(times, source_times, signal[:, c]) for c in range(signal.shape[1])], axis=1)
    else:
        output = signal
    if len(output) != target_length:
        raise ValueError(f'Resample length {len(output)} != {target_length}; inspect alignment.')
    return np.asarray(output, dtype=np.float32)


def align_labels(labels, target_rate, target_length, source_rate=700):
    """Assign only target sample intervals fully inside an original constant state."""
    labels = np.asarray(labels)
    changes = np.r_[0, np.flatnonzero(labels[1:] != labels[:-1]) + 1, len(labels)]
    output = np.full(target_length, -1, dtype=np.int64)
    for start, end in zip(changes[:-1], changes[1:]):
        value = labels[start]
        if value in (1, 2, 3):
            lo = (int(start) * target_rate + source_rate - 1) // source_rate
            hi = int(end) * target_rate // source_rate
            output[lo:min(hi, target_length)] = int(value) - 1
    return output

"""Frozen rotating grouped subject splits; never random window splits."""
import random
from collections import Counter
from pathlib import Path
from src.utils.tracking import canonical, digest, read_json

SUBJECTS = ['S2', 'S3', 'S4', 'S5', 'S6', 'S7', 'S8', 'S9', 'S10', 'S11', 'S13', 'S14', 'S15', 'S16', 'S17']


def create_manifest(seed=42):
    order = SUBJECTS.copy()
    random.Random(seed).shuffle(order)
    groups = [order[i:i + 3] for i in range(0, 15, 3)]
    folds = [{'fold_id': k + 1, 'test': groups[k], 'validation': groups[(k + 1) % 5],
              'train': [s for j, group in enumerate(groups) if j not in {k, (k + 1) % 5} for s in group]}
             for k in range(5)]
    return {'protocol': 'grouped_subject_wise_5fold', 'algorithm_version': 'python-random-rotate-v1',
            'split_seed': seed, 'original_subject_order': SUBJECTS, 'shuffled_subject_order': order,
            'groups': groups, 'folds': folds}


def validate_manifest(manifest):
    if manifest != create_manifest(manifest['split_seed']):
        raise ValueError('Manifest differs from the specified deterministic algorithm.')
    for role, count in [('train', 3), ('validation', 1), ('test', 1)]:
        counts = Counter(s for fold in manifest['folds'] for s in fold[role])
        if counts != Counter({s: count for s in SUBJECTS}):
            raise ValueError('Subject coverage failure.')
    for fold in manifest['folds']:
        sets = [set(fold[r]) for r in ('train', 'validation', 'test')]
        if [len(x) for x in sets] != [9, 3, 3] or len(set.union(*sets)) != 15:
            raise ValueError('Subject overlap or invalid fold size.')
    return manifest


def load_manifest(path):
    path = Path(path)
    manifest = read_json(path)
    if path.with_suffix('.sha256').read_text().strip() != digest(manifest):
        raise ValueError('Split manifest checksum mismatch.')
    return validate_manifest(manifest)


def ensure_manifest(path, seed=42):
    path = Path(path)
    if path.exists():
        manifest = load_manifest(path)
        if manifest['split_seed'] != seed:
            raise ValueError('Existing manifest uses another seed; never overwrite it.')
        return manifest
    if path.with_suffix('.sha256').exists():
        raise ValueError('Orphan checksum exists; refusing to overwrite.')
    manifest = validate_manifest(create_manifest(seed))
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(canonical(manifest))
    path.with_suffix('.sha256').write_text(digest(manifest) + '\n', encoding='ascii')
    return manifest

"""Windows anchored independently inside each uninterrupted valid label region."""
import numpy as np


def make_windows(signal, labels, subject, rate=32, window_seconds=30, stride_seconds=15):
    size, stride = int(rate * window_seconds), int(rate * stride_seconds)
    if size <= 0 or stride <= 0 or len(signal) != len(labels):
        raise ValueError('Invalid window settings or label alignment.')
    boundaries = np.r_[0, np.flatnonzero(labels[1:] != labels[:-1]) + 1, len(labels)]
    windows, rows = [], []
    short_regions = 0
    for lo, hi in zip(boundaries[:-1], boundaries[1:]):
        if labels[lo] < 0:
            continue
        short_regions += int(hi - lo < size)
        for start in range(int(lo), int(hi) - size + 1, stride):
            windows.append(signal[start:start + size].T)
            rows.append({'subject_id': subject, 'window_id': f'{subject}_{start}_{start + size}',
                         'start_time': start / rate, 'end_time': (start + size) / rate,
                         'original_label': int(labels[start]) + 1, 'label': int(labels[start])})
    if not windows:
        raise ValueError(f'{subject}: no valid complete windows')
    # Rejection audit for a fixed global grid (retained windows use region-local anchors).
    rejected = {'invalid_region': 0, 'transition': 0}
    for start in range(0, len(labels) - size + 1, stride):
        region = labels[start:start + size]
        if (region < 0).any():
            rejected['invalid_region'] += 1
        elif not (region == region[0]).all():
            rejected['transition'] += 1
    report = {'kept_region_anchored_windows': len(rows), 'short_valid_regions': short_regions,
              'global_grid_rejections': rejected, 'global_grid_candidates': max(0, (len(labels) - size) // stride + 1),
              'policy': 'region-local anchors; global-grid rejection counts are a separate audit'}
    return np.stack(windows).astype(np.float32), rows, report

"""Read-only, schema-aware committed history shared by import and plotting."""
import csv
from dataclasses import dataclass
import json
from pathlib import Path
import re
import numpy as np
from src.training.checkpoint import load_checkpoint
from src.evaluation.metrics import classification_metrics
from src.utils.config import ROOT
from src.utils.tracking import read_json, file_hash

INTEGER_FIELDS = {'epoch', 'fold_id', 'training_seed', 'best_epoch', 'batch_index', 'global_step', 'batch_size', 'true_label', 'predicted_label', 'label', 'original_label', 'windows'}
TEXT_FIELDS = {'run_id', 'attempt_id', 'timestamp', 'subject_id', 'window_id'}


def parse_value(key, value):
    if value is None or value in ('', 'N/A', 'None', 'null'):
        return None
    if key in TEXT_FIELDS:
        return value
    if key == 'is_best_checkpoint':
        return str(value).lower() == 'true'
    if str(value).startswith(('[', '{')):
        return json.loads(value)
    if key in INTEGER_FIELDS:
        return int(value)
    try:
        value = float(value)
        return value if np.isfinite(value) else None
    except ValueError:
        return value


def read_csv(path):
    with Path(path).open(encoding='utf-8', newline='') as stream:
        return [{k: parse_value(k, v) for k, v in row.items()} for row in csv.DictReader(stream)]


def epoch_key(row):
    return str(row.get('attempt_id', '')), int(row['epoch'])


def merged_epochs(path, committed):
    merged = {}
    for candidate in (path, path.with_name(path.stem + '.v2.csv')):
        if not candidate.exists():
            continue
        seen = set()
        for row in read_csv(candidate):
            key = epoch_key(row)
            if key in seen:
                raise ValueError(f'Duplicate epoch record: {candidate}, {key}')
            seen.add(key)
            if key in committed:
                merged.setdefault(key, {}).update({k: v for k, v in row.items() if v is not None})
    return [merged[key] for key in sorted(committed, key=lambda key: key[1]) if key in merged]


@dataclass
class FoldHistory:
    folder: Path
    metadata: dict
    epochs: list
    validation: list
    iterations: list
    test: dict
    predictions: list
    orphan_iterations: int


def resolve_group(group_id, root=ROOT):
    if not re.fullmatch(r'[A-Za-z0-9_-]+', group_id):
        raise ValueError('Invalid group ID.')
    matches = list((Path(root) / 'runs').glob('*/' + group_id))
    if len(matches) != 1:
        raise ValueError(f'Expected exactly one experiment group, found {len(matches)} for {group_id}.')
    return matches[0]


def read_group(group_id, root=ROOT):
    root = Path(root)
    group = resolve_group(group_id, root)
    manifest = read_json(group / 'experiment_manifest.json')
    folds, sources, all_windows = [], set([group / 'experiment_manifest.json']), set()
    for folder in sorted(group.glob('seed_*/fold_*')):
        metadata = read_json(folder / 'metadata.json')
        if metadata['status'] != 'completed':
            continue
        marker = folder / 'completion.json'
        if marker.exists():
            for relative, checksum in read_json(marker)['files'].items():
                if file_hash(folder / relative) != checksum:
                    raise ValueError(f'Historical artifact checksum mismatch: {folder / relative}')
        checkpoint_path = folder / 'checkpoints/last.pt'
        state = load_checkpoint(checkpoint_path)
        committed = {epoch_key(r) for r in state['history']}
        epochs = merged_epochs(folder / 'logs/epochs.csv', committed)
        validation = merged_epochs(folder / 'logs/validation.csv', committed)
        if len(epochs) != metadata['completed_epochs'] or len(validation) != len(epochs):
            raise ValueError('Missing committed epoch/validation logs.')
        batch_rows = read_csv(folder / 'logs/iterations.csv')
        iterations = [row for row in batch_rows if epoch_key(row) in committed]
        keys = [(r['attempt_id'], r['epoch'], r['batch_index']) for r in iterations]
        if len(set(keys)) != len(keys):
            raise ValueError('Duplicate committed training batches.')
        predictions = read_csv(folder / 'metrics/predictions.csv')
        for row in predictions:
            key = (metadata['training_seed'], row['subject_id'], row['window_id'])
            if key in all_windows:
                raise ValueError('Duplicate OOF window across folds.')
            all_windows.add(key)
        test = read_json(folder / 'metrics/test.json')
        recomputed = classification_metrics([r['true_label'] for r in predictions], [r['predicted_label'] for r in predictions])
        for key in ('accuracy', 'macro_f1', 'balanced_accuracy'):
            if key in test and not np.isclose(test[key], recomputed[key], atol=1e-12, rtol=0):
                raise ValueError('Historical predictions and metrics disagree.')
        # Test accuracy can be derived from complete predictions; epoch accuracy cannot.
        test.setdefault('accuracy', recomputed['accuracy'])
        folds.append(FoldHistory(folder, metadata, epochs, validation, iterations, test, predictions, len(batch_rows) - len(iterations)))
        sources.update([checkpoint_path, folder / 'metadata.json', folder / 'metrics/test.json', folder / 'metrics/predictions.csv'])
        sources.update((folder / 'logs').glob('*.csv'))
    if not folds:
        raise ValueError('No completed folds with usable history.')
    result = root / 'results' / group.parent.name / group.name
    source_hashes = {p.relative_to(root).as_posix(): file_hash(p) for p in sorted(sources)}
    return {'root': root, 'group': group, 'result': result, 'manifest': manifest, 'folds': folds, 'source_hashes': source_hashes}

"""CNN-1D baseline, trained from scratch; outputs unnormalized logits."""
from torch import nn


class CNN1D(nn.Module):
    def __init__(self, input_channels=5, num_classes=3):
        super().__init__()
        self.network = nn.Sequential(
            nn.Conv1d(input_channels, 32, 7, padding=3), nn.BatchNorm1d(32), nn.ReLU(), nn.MaxPool1d(2),
            nn.Conv1d(32, 64, 5, padding=2), nn.BatchNorm1d(64), nn.ReLU(), nn.MaxPool1d(2),
            nn.Conv1d(64, 128, 3, padding=1), nn.BatchNorm1d(128), nn.ReLU(),
            nn.AdaptiveAvgPool1d(1), nn.Flatten(), nn.Linear(128, 64), nn.ReLU(), nn.Dropout(0.3), nn.Linear(64, num_classes))

    def forward(self, x):
        return self.network(x)

"""Keep best model selection separate from significant-improvement patience."""
class SelectionState:
    def __init__(self, patience, min_delta):
        self.patience, self.min_delta = patience, min_delta
        self.best_score, self.best_loss, self.anchor = -1.0, float('inf'), -1.0
        self.best_epoch, self.bad_epochs = 0, 0

    def update(self, score, loss, epoch):
        better = score > self.best_score + 1e-12 or (abs(score - self.best_score) <= 1e-12 and loss < self.best_loss)
        if better:
            self.best_score, self.best_loss, self.best_epoch = score, loss, epoch
        if score > self.anchor + self.min_delta:
            self.anchor, self.bad_epochs = score, 0
        else:
            self.bad_epochs += 1
        return better, self.bad_epochs >= self.patience

"""Fold-local weighted loss and Adam optimizer."""
import numpy as np
import torch


def make_optimizer(model, config):
    return torch.optim.Adam(model.parameters(), lr=config['learning_rate'], weight_decay=config['weight_decay'])


def class_weights(labels):
    counts = np.bincount(labels, minlength=3)
    if (counts == 0).any():
        raise ValueError('Training subjects must contain all three classes.')
    return torch.tensor(len(labels) / (3 * counts), dtype=torch.float32)

"""Configuration and project-relative paths, independent of the caller's cwd."""
from pathlib import Path
import copy
import os
import yaml

ROOT = Path(__file__).resolve().parents[2]


def merge(base, override):
    result = copy.deepcopy(base)
    for key, value in override.items():
        result[key] = merge(result.get(key, {}), value) if isinstance(value, dict) else value
    return result


def load_config(path=None):
    config = yaml.safe_load((ROOT / 'configs/default.yaml').read_text(encoding='utf-8'))
    if path:
        config = merge(config, yaml.safe_load((ROOT / path).read_text(encoding='utf-8')))
    if config['experiment']['status'] == 'planned':
        raise NotImplementedError('This experiment is planned; only E1 is implemented.')
    if config['data']['max_windows_per_subject'] is not None:
        raise ValueError('Research runs must use every valid window.')
    if config['split']['protocol'] != 'grouped_subject_wise_5fold' or config['split']['split_seed'] != 42:
        raise ValueError('The official protocol requires the fixed seed42 five-fold manifest.')
    if config['experiment']['model'] != 'cnn1d' or config['selection'] != {'metric': 'val_macro_f1', 'mode': 'max', 'tie_breaker': 'val_loss'}:
        raise ValueError('Unsupported model/selection protocol.')
    if config['data']['labels'] != [1, 2, 3] or config['runtime']['parallel_folds'] != 1:
        raise ValueError('E1 uses labels 1/2/3 and sequential folds.')
    if config['training']['optimizer'] != 'adam' or config['training']['loss'] != 'weighted_cross_entropy':
        raise ValueError('Unsupported optimizer or loss.')
    if not all(config['logging'][key] for key in ('log_every_iteration', 'log_every_epoch', 'flush_each_iteration')):
        raise ValueError('Complete live logging is mandatory.')
    tc = config['training']
    if not tc['seeds'] or len(set(tc['seeds'])) != len(tc['seeds']) or not all(isinstance(seed, int) and 0 <= seed < 2**32 for seed in tc['seeds']):
        raise ValueError('Training seeds must be distinct uint32 integers.')
    if any(tc[key] <= 0 for key in ('max_epochs', 'batch_size', 'learning_rate', 'early_stopping_patience', 'gradient_clip_norm')) or tc['early_stopping_min_delta'] < 0 or tc['weight_decay'] < 0:
        raise ValueError('Invalid training hyperparameters.')
    sensors = config['data']['sensors']
    if not sensors or len(set(sensors)) != len(sensors) or not set(sensors) <= {'ACC', 'BVP', 'EDA'}:
        raise ValueError('Unsupported or duplicate sensors.')
    from src.utils.tensorboard_tracker import tracking_options
    tracking_options(config)
    return config


def same_training_config(left, right):
    """Monitoring can change on resume; computation, selection and splits cannot."""
    return {k: v for k, v in left.items() if k not in ('logging', 'tracking')} == {k: v for k, v in right.items() if k not in ('logging', 'tracking')}


def raw_root():
    return Path(os.environ.get('WESAD_ROOT', ROOT / 'data/raw/WESAD')).resolve()

"""Deterministic initialization and complete epoch-boundary RNG recovery."""
import random
import numpy as np
import torch


def seed_everything(seed, deterministic=True, threads=2):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)
    torch.set_num_threads(threads)
    torch.use_deterministic_algorithms(deterministic)
    torch.backends.cudnn.benchmark = False
    torch.backends.cudnn.deterministic = deterministic


def rng_state():
    return {'python': random.getstate(), 'numpy': np.random.get_state(), 'torch': torch.get_rng_state(),
            'cuda': torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None}


def restore_rng(state):
    random.setstate(state['python'])
    np.random.set_state(state['numpy'])
    torch.set_rng_state(state['torch'].cpu())
    if state['cuda'] is not None and torch.cuda.is_available():
        torch.cuda.set_rng_state_all([s.cpu() for s in state['cuda']])

"""Capture the actual runtime and dependency versions for each group."""
